import{_ as a,H as t,f as e,i as I}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"Q28 | 人才画像：AI时代企业对研发人才技能新要求？","description":"","frontmatter":{},"headers":[],"relativePath":"致程序员：AI百问百答/Q28｜人才画像：AI时代企业对研发人才技能新要求？.md","filePath":"致程序员：AI百问百答/Q28｜人才画像：AI时代企业对研发人才技能新要求？.md","lastUpdated":1795559851000}'),p={name:"致程序员：AI百问百答/Q28｜人才画像：AI时代企业对研发人才技能新要求？.md"};function A(i,_,l,o,r,n){return t(),e("div",null,[..._[0]||(_[0]=[I('<h1 id="q28-人才画像-ai时代企业对研发人才技能新要求" tabindex="-1">Q28 | 人才画像：AI时代企业对研发人才技能新要求？ <a class="header-anchor" href="#q28-人才画像-ai时代企业对研发人才技能新要求" aria-label="Permalink to &quot;Q28 | 人才画像：AI时代企业对研发人才技能新要求？&quot;">​</a></h1><ul><li>作者介绍：万学凡，凯捷中国副总裁、数字化团队负责人鲁四喜，某大厂金融科技创新业务质量负责人</li></ul><p>Q：AI 时代，企业里对研发同学的能力画像，有哪些新的要求？</p><p>万学凡：部分企业要求研发团队应用 AI 工具，如使用 Copilot 或通过 AI 生成测试用例、代码，并将 AI 相关量化指标纳入研发 KPI、OKR，例如设定 AI 生成代码比率等目标。也有企业虽未以 KPI 硬性要求，但明确鼓励团队积极使用 AI 工具。当前行业仍处于探索阶段，企业在拥抱 AI 的同时，也在探寻能有效激励团队的高效度量方式。</p><p>我所在的凯捷中国数字化团队，为企业提供 IT 咨询规划、业务方案设计、架构设计及落地实施服务，我们对团队成员的要求还是要具备较强的业务架构、应用架构和技术架构能力。</p><p>在 AI 相关技能方面，我们对团队成员提出三点要求：</p><ul><li><p>第一，理解提示词工程并善于使用 AI 工具；</p></li><li><p>第二，了解 AI 大模型发展趋势，能够运用 AI 开发工具与应用；</p></li><li><p>第三，具备较强的学习能力。我们目前团队中负责 AI 工作的同事，并非 AI 专业出身，但凭借出色的自学能力胜任岗位。</p></li></ul><p>在面试时，我们也会考察候选人的学习能力与学习意愿，例如是否能清晰阐述不同的业务场景如何选型不同的模型，而非机械背诵知识点。凯捷全球团队开发了 AI 相关培训课程，我们也要求内部研发人员去学习。同时，我们在内部搭建了 Dify 平台，鼓励团队使用，并将 AI 代码使用率纳入团队 KPI。这一举措于今年启动，目前处于首个周期，后续将进行复盘与优化。</p><p>鲁四喜：我们在招聘实习生或毕业生时，会重点考察候选人的 AI 能力，包括机器学习基础知识、AI 大语言模型的基本原理及应用能力。例如，候选人需要了解微调与 RAG 的优缺点、是否掌握微调技术、熟悉主流 RAG 框架、能够进行 foundation model 选型， 以及清楚 LLM 自身的优缺点。此外，我们还会关注候选人过往参与的项目，特别是如何运用 LLM 能力解决实际问题的经历。</p><p>对于现有全职员工，若参与 AI 相关的独立探索项目，同样需要具备上述能力。</p>',10)])])}const c=a(p,[["render",A]]);export{d as __pageData,c as default};
